    const taskCards=visibleTasks.length?visibleTasks.map(task=>{const assignee=members.find(item=>item.id===task.assignee_ids[0]),taskReviews=reviews.filter(item=>item.task_id===task.id),actions=[];if(task.status==="todo"&&canWork(task))actions.push(`<button type="button" class="button primary" data-workflow-transition="in_progress">開始</button>`);if(task.status==="in_progress"&&canWork(task))actions.push(task.requires_review?`<button type="button" class="button primary" data-workflow-transition="review">送交審核</button>`:`<button type="button" class="button primary" data-workflow-transition="done">完成</button>`);if(["todo","in_progress"].includes(task.status)&&elevated)actions.push(`<button type="button" class="button danger" data-workflow-transition="cancelled">取消</button>`);if(task.status==="review"&&reviewer)actions.push(`<input name="review_comment" maxlength="1000" placeholder="審核意見"><button type="button" class="button primary" data-workflow-review="approved">核准並完成</button><button type="button" class="button" data-workflow-review="changes_requested">要求修改</button>`);return `<article class="engineering-workflow-task" data-task-id="${esc(task.id)}"><header><div><span class="engineering-task-status">${esc(task.status)}</span><b>${esc(task.title)}</b><small>${esc(task.priority)}${task.due_at?` · 到期 ${esc(String(task.due_at).slice(0,10))}`:""}</small></div><span>${task.requires_review?"需審核":"一般 Task"}</span></header><p>${esc(task.description||"無說明")}</p><p><small>負責人：${esc(assignee?.display_name||"未指派")}${task.related_entity_type?` · 關聯 ${esc(task.related_entity_type)} / ${esc(task.related_entity_id)}`:""}</small></p>${elevated&&!['done','cancelled'].includes(task.status)?`<div class="engineering-workflow-assign"><select name="assignee_id">${assigneeOptions.replace(`value="${esc(task.assignee_ids[0]||"")}"`,`value="${esc(task.assignee_ids[0]||"")}" selected`)}</select><button type="button" class="button" data-workflow-assign="1">指派</button></div>`:""}<div class="engineering-actions">${actions.join("")}</div>${taskReviews.map(item=>`<small class="engineering-review-history">${esc(item.decision)} · ${esc(members.find(member=>member.id===item.reviewer_id)?.display_name||item.reviewer_id)}${item.comment?` · ${esc(item.comment)}`:""}</small>`).join("")}</article>`;}).join(""):`<p class="engineering-muted">沒有符合的任務。</p>`;
